Create one empty array per column (as many as the longest row has items), then push each row's value at index `i` into column `i`. This is a transpose: rows become columns.

```js
const unzip = rows => {
  const cols = Array.from(
    { length: Math.max(...rows.map(r => r.length)) },
    () => []
  );
  for (const row of rows) row.forEach((v, i) => cols[i].push(v));
  return cols;
};

