```js
const collection = {
  objects: [],
  index: new Map(),
  add(...objects) {
    objects.forEach(obj => {
      if (this.index.has(obj.id))
        throw new Error(`Object with ID ${obj.id} already exists`);
      this.objects.push(obj);
      this.index.set(obj.id, obj);
    });
  },
  get(id) {
    return this.index.get(id); // O(1), no scan
  },
  remove(id) {
    const obj = this.index.get(id);
    if (!obj) return;
    this.objects.splice(this.objects.indexOf(obj), 1);
    this.index.delete(id);
  },
};

