Schedule a frame with `requestAnimationFrame`, call the callback inside it, then schedule the next frame again while a `running` flag is true. `stop` clears the flag and cancels the pending frame with `cancelAnimationFrame(id)`.

```js
const recordAnimationFrames = (callback, autoStart = true) => {
  let running = false, raf;
  const run = () => {
    raf = requestAnimationFrame(time => {
      callback(time);
      if (running) run();
    });
  };
  const start = () => { if (!running) { running = true; run(); } };
  const stop = () => { running = false; cancelAnimationFrame(raf); };
  if (autoStart) start();
  return { start, stop };
};

const rec = recordAnimationFrames(t => progressBar.style.width = `${(t / 50) % 100}%`);
rec.stop();
```

