```js
const renderElement = ({ type, props = {} }, container) => {
  const el = type ? document.createElement(type) : document.createTextNode('');
  for (const [key, value] of Object.entries(props)) {
    if (key === 'children') continue;
    if (type && key.startsWith('on'))
      el.addEventListener(key.slice(2).toLowerCase(), value); // onClick -> click
    else el[key] = value; // className, type, nodeValue...
  }
  props.children?.forEach(child => renderElement(child, el));
  container.append(el);
};

