```js
const log = new Proxy({}, {
  set(target, key, value) {
    if (key in target) return false; // no overwrites
    if (!/^\d{4}-\d{2}-\d{2}$/.test(key)) return false; // date-like keys only
    target[key] = value;
    return true;
  },
});

