```css
/* Flexbox */
body {
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}
main { flex: 1; }

/* Grid */
body {
  min-height: 100dvh;
  display: grid;
  grid-template-rows: auto 1fr auto;  /* header, main, footer */
}
```

