@media print {
  nav, header, footer, aside, form, button { display: none; }

  body { margin: 0; font: 12pt/1.5 Georgia, serif; color: #000; }
  h1 { font-size: 24pt; }

  img { max-width: 100%; }
  img, table, figure { break-inside: avoid; }
  h2, h3 { break-after: avoid; }

  a[href^="http"]::after { content: " (" attr(href) ")"; }
}

@page { margin: 2cm; }
```

