    set: (key, value) => setMap(prev => new Map(prev).set(key, value)),
    remove: key => setMap(prev => {
      const next = new Map(prev);
      next.delete(key);
      return next;
    }),
    clear: () => setMap(new Map()),
  }), []);
  return [map, actions];
}

// const [cart, { set, remove }] = useMap([['apples', 10]]);
