Pass a **function** to `useState` (lazy initialization) so `localStorage.getItem` and `JSON.parse` run only on the first render. Wrap storage access in `try/catch` because it can throw: storage may be disabled or full (`QuotaExceededError`), and the stored text may not be valid JSON.

```jsx
function useLocalStorage(key, defaultValue) {
  const [value, setValue] = useState(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw !== null ? JSON.parse(raw) : defaultValue;
    } catch {
      return defaultValue;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {}
  }, [key, value]);

  return [value, setValue];
}

// const [theme, setTheme] = useLocalStorage('theme', 'light');
```

Writing in an effect means `setValue(prev => ...)` works like normal state. Limits: changing `key` doesn't reload the value, other tabs aren't synced (listen for the `storage` event), and `localStorage` doesn't exist during server rendering.

`sessionStorage` is scoped to **one tab** and is cleared when that tab closes; `localStorage` is shared by all tabs of the same origin and survives browser restarts. Choose `sessionStorage` for data that belongs to one visit, such as a half-filled multi-step form, so it survives a reload but doesn't leak into other tabs or next week.

```jsx
function useStoredState(key, defaultValue, storage = sessionStorage) {
  const [value, setValue] = useState(() => {
    try {
      const raw = storage.getItem(key);
      return raw !== null ? JSON.parse(raw) : defaultValue;
    } catch {
      return defaultValue;
    }
  });
  useEffect(() => {
    try { storage.setItem(key, JSON.stringify(value)); } catch {}
  }, [key, value, storage]);
  return [value, setValue];
}

// const [step, setStep] = useStoredState('checkout-step', 1);
```

Both APIs store strings only (hence `JSON.stringify`), are synchronous, and are readable by any script on the page, so never store tokens or secrets there.

