function useForceUpdate() {
  const [, forceUpdate] = useReducer(x => x + 1, 0);
  return forceUpdate;
}

// Usually better: tell React about the outside data
const cart = useSyncExternalStore(cartStore.subscribe, cartStore.getSnapshot);
```

