function subscribe(notify) {
  window.addEventListener('online', notify);
  window.addEventListener('offline', notify);
  return () => {
    window.removeEventListener('online', notify);
    window.removeEventListener('offline', notify);
  };
}

function useOnline() {
  return useSyncExternalStore(subscribe, () => navigator.onLine, () => true);
}

function SaveStatus() {
  return useOnline() ? null : <p role="status">You're offline. Changes will sync later.</p>;
}
```

The third argument is the server snapshot (assume online). Treat failed `fetch` calls as the real signal and handle them anyway.

